:root {
  --card-bg: #f2e8d5;
  --card-border: #8b6b3d;
  --header-bg: #3b2a14;
  --header-text: #f2e8d5;
  --header-sub: #c9a96e;
  --badge-bg: #c9a96e;
  --badge-text: #3b2a14;
  --label-color: #7a5c30;
  --value-color: #2c1a06;
  --divider-color: #c9a96e;
  --type-badge-bg: #3b2a14;
  --type-badge-text: #f2e8d5;
  --type-badge-alt-bg: #8b6b3d;
  --stage-bg: #e0cba8;
  --stage-border: #8b6b3d;
  --stage-done-bg: #3b2a14;
  --stage-done-text: #f2e8d5;
  --stage-active-bg: #c9a96e;
  --stage-active-text: #2c1a06;
  --stage-text: #7a5c30;
  --footer-bg: #3b2a14;
  --footer-text: #f2e8d5;
  --footer-label: #c9a96e;
  --seal-color: #c9a96e;
  --detail-cell-bg: #e8d8b8;
  --detail-border: #c9a96e;
}

article.mount-card {
  width: 480px;
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 6px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.card-header {
  background-color: var(--header-bg);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.studio-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 3px 7px;
  border-radius: 3px;
  white-space: nowrap;
}

.studio-name {
  color: var(--header-text);
  font-size: 20px;
  font-weight: 800;
  margin: 0;
  letter-spacing: 0.03em;
  line-height: 1.1;
}

.studio-sub {
  color: var(--header-sub);
  font-size: 11px;
  margin: 0;
  letter-spacing: 0.06em;
  font-style: italic;
  margin-left: auto;
  white-space: nowrap;
}

.card-body {
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.specimen-block {
  display: flex;
  align-items: center;
  gap: 12px;
}

.specimen-icon {
  font-size: 44px;
  line-height: 1;
}

.specimen-info {
  flex: 1;
  display: grid;
  grid-template-columns: auto 1fr;
  column-gap: 8px;
  row-gap: 2px;
  align-items: baseline;
}

.label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--label-color);
  text-transform: uppercase;
  margin: 0;
}

.value {
  font-size: 13px;
  font-weight: 700;
  color: var(--value-color);
  margin: 0;
}

.italic {
  font-style: italic;
  font-weight: 400;
  font-size: 12px;
}

.top-gap {
  margin-top: 6px;
}

.mount-type {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}

.type-badge {
  background-color: var(--type-badge-bg);
  color: var(--type-badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 3px;
  letter-spacing: 0.05em;
  margin: 0;
}

.type-badge.alt {
  background-color: var(--type-badge-alt-bg);
}

.divider {
  height: 1px;
  background-color: var(--divider-color);
  border: none;
}

.details-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.detail-cell {
  background-color: var(--detail-cell-bg);
  border: 1px solid var(--detail-border);
  border-radius: 4px;
  padding: 5px 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.detail-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--label-color);
}

.detail-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--value-color);
}

.stages {
  display: flex;
  gap: 4px;
}

.stage {
  flex: 1;
  text-align: center;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  padding: 5px 4px;
  border-radius: 4px;
  border: 1px solid var(--stage-border);
  background-color: var(--stage-bg);
  color: var(--stage-text);
  text-transform: uppercase;
}

.stage.done {
  background-color: var(--stage-done-bg);
  color: var(--stage-done-text);
  border-color: var(--stage-done-bg);
}

.stage.active {
  background-color: var(--stage-active-bg);
  color: var(--stage-active-text);
  border-color: var(--card-border);
}

.card-footer {
  background-color: var(--footer-bg);
  padding: 8px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-left,
.footer-right {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.footer-right {
  align-items: flex-end;
}

.footer-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--footer-label);
}

.footer-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--footer-text);
}

.footer-seal {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--seal-color);
  border: 1px solid var(--seal-color);
  padding: 4px 12px;
  border-radius: 3px;
}
